'use strict';

/**
 * NodeJs-Unreal bundled drop-in for the `ipc-event-emitter` npm package.
 *
 * Wire-compatible: messages over a real IPC channel use the same envelope the
 * original package uses, `{ type: 'ipc-event-emitter', emit: [name, ...args] }`,
 * so the genuine npm package and this one interoperate.
 *
 * Three transports, chosen automatically:
 *   - Forked subprocess: a real IPC channel exists (`process.send` + channel).
 *   - Worker thread:     started by process.js via workerBootstrap.js, talks over parentPort.
 *   - Inline script:     require()'d inside process.js, binds to the Unreal bridge
 *                        process.js installs on globalThis.
 *
 * Usage in a script (identical to the npm package):
 *   const ipc = require('ipc-event-emitter').default(process);
 *   ipc.on('myevent', (vars) => ipc.emit('result', compute(vars)));
 *
 * NodeJs-Unreal extras:
 *   - ipc.args               launch args from the component's Script Params -> Args
 *   - ipc.on('shouldExit')   fired before the script is stopped or reloaded; clean up
 *                            sockets/servers here (timers are cleared for you inline)
 *   - Emit Event With Callback: the handler gets a trailing callback, call it to reply
 *                            e.g. ipc.on('ask', (q, reply) => reply(answer(q)))
 */

const EventEmitter = require('events');

const TYPE = 'ipc-event-emitter';
const ACK_TYPE = 'nue-ack';
const EXIT_TYPE = 'nue-exit';
const EXIT_EVENT = 'shouldExit';

let workerThreads = null;
try { workerThreads = require('worker_threads'); } catch (e) { /* very old node */ }

// Structured clone (worker postMessage) turns Buffers into plain Uint8Arrays; rewrap them.
function toBuffers(value) {
	if (value instanceof Uint8Array) {
		return Buffer.isBuffer(value) ? value : Buffer.from(value.buffer, value.byteOffset, value.byteLength);
	}
	if (Array.isArray(value)) {
		return value.map(toBuffers);
	}
	if (value && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
		const out = {};
		for (const k of Object.keys(value)) out[k] = toBuffers(value[k]);
		return out;
	}
	return value;
}

class IPCEventEmitter extends EventEmitter {
	constructor($process) {
		super();
		this._process = $process;
		this._transport = null;
		this._exited = false;
		this.args = [];

		const wt = workerThreads;
		const bridge = globalThis.__unrealBridge;

		if (wt && !wt.isMainThread && wt.parentPort && wt.workerData && wt.workerData.__nodeJsUnreal) {
			this._transport = 'worker';
			this._port = wt.parentPort;
			this._port.on('message', (data) => this._onMessage(data));
			this.args = (wt.workerData.args || []).slice();
		} else if ($process && typeof $process.send === 'function' && typeof $process.on === 'function' && $process.channel) {
			this._transport = 'channel';
			$process.on('message', (data) => this._onMessage(data));
			// Parent went away (stopped or Unreal closed): last chance to clean up.
			$process.on('disconnect', () => this._emitExit());
			this.args = process.argv.slice(2);
		} else if (bridge && bridge.version >= 2) {
			this._transport = 'inline';
			this._bridge = bridge;
			this._ctx = bridge.context();
			bridge.register(this._ctx, this);
			this.args = (this._ctx && this._ctx.args) ? this._ctx.args.slice() : [];
		} else {
			// Not running under NodeJs-Unreal (e.g. `node myscript.js`); emits are no-ops.
			this.args = process.argv.slice(2);
		}
	}

	_onMessage(data) {
		if (!data || typeof data !== 'object') return;
		if (data.type === TYPE && Array.isArray(data.emit) && data.emit.length) {
			const name = data.emit[0];
			const args = toBuffers(data.emit.slice(1));
			if (data.ack !== undefined && data.ack !== null) {
				args.push(this._makeAck(data.ack));
			}
			super.emit(name, ...args);
		} else if (data.type === EXIT_TYPE) {
			this._emitExit();
		}
	}

	_makeAck(id) {
		let done = false;
		return (...result) => {
			if (done) return;
			done = true;
			this._send({ type: ACK_TYPE, ack: id, args: result });
		};
	}

	_emitExit() {
		if (this._exited) return;
		this._exited = true;
		super.emit(EXIT_EVENT);
	}

	_send(message) {
		try {
			if (this._transport === 'worker') {
				this._port.postMessage(message);
			} else if (this._transport === 'channel' && this._process.connected) {
				this._process.send(message);
			}
		} catch (e) {
			// A closed channel is expected during shutdown; anything else (e.g. an arg that
			// can't be cloned, like a function) would silently drop the event, so say so.
			if (e && e.code !== 'ERR_IPC_CHANNEL_CLOSED') {
				console.error(`ipc-event-emitter: could not send '${message.emit ? message.emit[0] : message.type}': ${e.message}`);
			}
		}
	}

	/** Called by process.js to deliver an incoming Unreal->script event (inline path). */
	_deliver(name, args) {
		if (name === EXIT_EVENT) {
			this._emitExit();
			return;
		}
		super.emit(name, ...args);
	}

	emit(...args) {
		const name = args[0];

		// Never ship EventEmitter's internal bookkeeping events across the wire.
		if (name === 'newListener' || name === 'removeListener') {
			return super.emit.apply(this, args);
		}

		if (this._transport === 'inline') {
			this._bridge.sendEvent(this._ctx, name, args.slice(1));
		} else if (this._transport) {
			this._send({ type: TYPE, emit: args });
		}
		return this;
	}

	// Compatibility surface. The original package supports pinning (sticky events
	// for late listeners); for the Unreal bridge a plain emit is sufficient.
	pin(...args) {
		return this.emit(...args);
	}
	unpin() {
		return this;
	}
	fix() {
		return this;
	}
}

function IPC($process) {
	return new IPCEventEmitter($process);
}

module.exports = IPC;
module.exports.default = IPC;
module.exports.IPC = IPC;
module.exports.IPCEventEmitter = IPCEventEmitter;
